	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		SeedLot
	 */
		public SeedLot createSeedLot( CreateSeedLotCommand command ) {

		SeedLot entity = new SeedLot();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setSeedLotId( command.getSeedLotId() );
            entity.setLotNumber( command.getLotNumber() );
            entity.setGerminationRate( command.getGerminationRate() );
            entity.setTreatment( command.getTreatment() );
            entity.setQuantity( command.getQuantity() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of SeedLot {0} ", entity.toString() );

		return entity;
	}

